import * as THREE from 'three/webgpu'
import * as TSL from 'three/tsl'
import { bloom } from 'three/examples/jsm/tsl/display/BloomNode'

import { useEffect, useMemo, useRef, useState } from 'react'
import { Canvas, extend, useFrame, useThree } from '@react-three/fiber'
import { Environment, Lightformer } from '@react-three/drei'

const heroTarget = new THREE.Vector3()
const cameraTarget = new THREE.Vector3()
const lookAtTarget = new THREE.Vector3()
const poreScale = new THREE.Vector3(1, 1, 1)

const ATOM_AQUA = '#7ec8c8'
const ATOM_LIME = '#b8d66a'
const ATOM_BLUE = '#6eb4d8'
const BOND = '#9ad4d0'

const clamp = (value, min = 0, max = 1) => Math.min(Math.max(value, min), max)
const smooth = (start, end, value) => {
  const normalized = clamp((value - start) / (end - start))
  return normalized * normalized * (3 - 2 * normalized)
}
const lerp = THREE.MathUtils.lerp

/** Scroll beats */
const BEATS = {
  focusStart: 0.08,
  focusEnd: 0.32,
  poreInStart: 0.28,
  poreInEnd: 0.4,
  transitStart: 0.4,
  transitEnd: 0.68,
  clearStart: 0.55,
  clearEnd: 0.72,
  poreOutStart: 0.68,
  poreOutEnd: 0.8,
  brandStart: 0.78,
  brandEnd: 0.92,
}

function seededRandom(seed) {
  const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453
  return x - Math.floor(x)
}

function makeFieldLayout(count) {
  const items = []
  for (let i = 0; i < count; i += 1) {
    const r0 = seededRandom(i + 1)
    const r1 = seededRandom(i + 17)
    const r2 = seededRandom(i + 41)
    const r3 = seededRandom(i + 73)
    const r4 = seededRandom(i + 99)
    items.push({
      position: [(r0 - 0.5) * 14, (r1 - 0.5) * 8, (r2 - 0.5) * 10 - 1],
      rotation: [r3 * Math.PI, r4 * Math.PI, r0 * Math.PI],
      scale: 0.45 + r1 * 0.55,
      drift: 0.4 + r2 * 0.8,
      phase: r3 * Math.PI * 2,
      palette: i % 3,
    })
  }
  return items
}

export default function App() {
  const [progress, setProgress] = useState(0)

  useEffect(() => {
    const update = () => {
      const scrollable = document.documentElement.scrollHeight - window.innerHeight
      setProgress(scrollable > 0 ? clamp(window.scrollY / scrollable) : 0)
    }
    update()
    window.addEventListener('scroll', update, { passive: true })
    window.addEventListener('resize', update)
    return () => {
      window.removeEventListener('scroll', update)
      window.removeEventListener('resize', update)
    }
  }, [])

  const brandOpacity = smooth(BEATS.brandStart, BEATS.brandEnd, progress)
  const hintOpacity = 1 - smooth(0.02, 0.12, progress)

  return (
    <main className="experience-shell">
      <div className="canvas-stage">
        <Canvas
          dpr={[1, 1.5]}
          gl={(props) => {
            extend(THREE)
            const renderer = new THREE.WebGPURenderer({ ...props, antialias: false, alpha: true })
            return renderer.init().then(() => renderer)
          }}
          camera={{ position: [0, 0.4, 11], fov: 36, near: 0.1, far: 60 }}>
          <color attach="background" args={['#0a3d45']} />
          <fog attach="fog" args={['#0a3d45', 8, 28]} />
          <ambientLight intensity={1.2} color="#c8fff0" />
          <directionalLight position={[4, 6, 8]} intensity={1.4} color="#e8fff8" />
          <directionalLight position={[-5, -2, 3]} intensity={0.55} color="#5bb8c8" />
          <Scene progress={progress} />
          <Environment>
            <group rotation={[-Math.PI / 3, 0, 1]}>
              <Lightformer form="circle" intensity={8} color="#d7fff1" rotation-x={Math.PI / 2} position={[0, 5, -9]} scale={2} />
              <Lightformer form="circle" intensity={2} color="#88d9d3" rotation-y={-Math.PI / 2} position={[10, 1, 0]} scale={8} />
              <Lightformer form="ring" color="#5bb7bb" intensity={6} onUpdate={(self) => self.lookAt(0, 0, 0)} position={[4, 5, 2]} scale={5} />
            </group>
          </Environment>
          <Effects />
        </Canvas>

        <div className="scroll-hint" style={{ opacity: hintOpacity }}>
          Scroll to follow the molecule
        </div>

        <div className="brand-reveal" style={{ opacity: brandOpacity }}>
          <div className="brand-name">
            AAGAMI
            <span>
              SE
              <span className="brand-q">
                Q
                <i className="brand-q-dot" aria-hidden />
              </span>
            </span>
          </div>
          <p className="brand-tagline">Clarity in the fight against cancer</p>
        </div>
      </div>
      <div className="scroll-space" aria-hidden />
    </main>
  )
}

function Scene({ progress }) {
  return (
    <>
      <CameraRig progress={progress} />
      <MicroParticles progress={progress} />
      <FieldMolecules progress={progress} />
      <HeroMolecule progress={progress} />
      <Nanopore progress={progress} />
    </>
  )
}

function CameraRig({ progress }) {
  const { camera } = useThree()

  useFrame((_, delta) => {
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, progress)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progress)

    // Start wide, lock onto hero center, follow through pore, settle for brand
    const camZ = lerp(11, 7.2, focus)
    const throughZ = lerp(camZ, 5.4, transit)
    const finalZ = lerp(throughZ, 6.2, brand)

    cameraTarget.set(lerp(0.35, 0, focus) * (1 - brand), lerp(0.25, 0, focus), finalZ)
    lookAtTarget.set(0, 0, lerp(0.5, -1.2, transit) * (1 - brand * 0.5))

    camera.position.lerp(cameraTarget, 1 - Math.exp(-delta * 4.5))
    camera.lookAt(lookAtTarget)
    camera.fov = lerp(36, 30, focus)
    camera.updateProjectionMatrix()
  })

  return null
}

function AtomMaterial({ color, opacity = 1, emissiveIntensity = 0.25 }) {
  return (
    <meshPhysicalMaterial
      color={color}
      emissive={color}
      emissiveIntensity={emissiveIntensity}
      metalness={0.15}
      roughness={0.18}
      clearcoat={1}
      clearcoatRoughness={0.12}
      transmission={0.35}
      thickness={0.6}
      transparent
      opacity={opacity}
    />
  )
}

/** Ball-and-stick molecule: central atom + bonded tips */
function MoleculeMesh({ scale = 1, palette = 0, opacity = 1 }) {
  const tips = useMemo(() => {
    const aqua = ATOM_AQUA
    const lime = ATOM_LIME
    const blue = ATOM_BLUE
    const sets = [
      [
        { pos: [0.55, 0.32, 0.18], color: lime, r: 0.2 },
        { pos: [-0.48, 0.28, 0.22], color: aqua, r: 0.18 },
        { pos: [0.12, -0.52, 0.2], color: lime, r: 0.17 },
        { pos: [-0.1, 0.15, -0.55], color: blue, r: 0.19 },
        { pos: [0.42, -0.18, -0.35], color: aqua, r: 0.16 },
      ],
      [
        { pos: [0.5, 0.4, 0], color: blue, r: 0.18 },
        { pos: [-0.5, 0.35, 0.15], color: lime, r: 0.17 },
        { pos: [0, -0.5, 0.25], color: aqua, r: 0.2 },
        { pos: [0.2, 0.1, -0.52], color: lime, r: 0.16 },
      ],
      [
        { pos: [0.48, 0.25, 0.3], color: aqua, r: 0.17 },
        { pos: [-0.4, 0.4, -0.1], color: lime, r: 0.19 },
        { pos: [0.15, -0.45, -0.25], color: blue, r: 0.18 },
        { pos: [-0.3, -0.2, 0.48], color: aqua, r: 0.16 },
        { pos: [0.35, 0.05, -0.45], color: lime, r: 0.15 },
        { pos: [-0.05, 0.5, 0.2], color: blue, r: 0.14 },
      ],
    ]
    return sets[palette % sets.length]
  }, [palette])

  const coreColor = palette === 1 ? ATOM_BLUE : ATOM_AQUA

  return (
    <group scale={scale}>
      <mesh>
        <sphereGeometry args={[0.32, 32, 32]} />
        <AtomMaterial color={coreColor} opacity={opacity} emissiveIntensity={0.35} />
      </mesh>
      {tips.map((tip, i) => {
        const mid = tip.pos.map((v) => v * 0.5)
        const length = Math.hypot(...tip.pos) * 0.72
        return (
          <group key={i}>
            <mesh position={mid} quaternion={lookQuat(tip.pos)}>
              <cylinderGeometry args={[0.045, 0.045, length, 8]} />
              <meshPhysicalMaterial color={BOND} transparent opacity={opacity * 0.85} roughness={0.3} metalness={0.1} />
            </mesh>
            <mesh position={tip.pos}>
              <sphereGeometry args={[tip.r, 24, 24]} />
              <AtomMaterial color={tip.color} opacity={opacity} emissiveIntensity={0.28} />
            </mesh>
          </group>
        )
      })}
    </group>
  )
}

function lookQuat(dir) {
  const up = new THREE.Vector3(0, 1, 0)
  const target = new THREE.Vector3(...dir).normalize()
  const q = new THREE.Quaternion()
  q.setFromUnitVectors(up, target)
  return q
}

function FieldMolecules({ progress }) {
  const group = useRef()
  const layout = useMemo(() => makeFieldLayout(28), [])
  const clear = smooth(BEATS.clearStart, BEATS.clearEnd, progress)
  const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)

  useFrame((state) => {
    if (!group.current) return
    const t = state.clock.elapsedTime
    group.current.children.forEach((child, i) => {
      const item = layout[i]
      if (!item) return
      const bob = Math.sin(t * item.drift + item.phase) * 0.12
      const driftX = Math.cos(t * item.drift * 0.6 + item.phase) * 0.08
      child.position.set(item.position[0] + driftX, item.position[1] + bob, item.position[2])
      child.rotation.x = item.rotation[0] + t * 0.08 * item.drift
      child.rotation.y = item.rotation[1] + t * 0.12 * item.drift

      // Soften field as we lock onto hero; fully remove once past the pore
      const fade = (1 - focus * 0.45) * (1 - clear)
      child.visible = fade > 0.02
      child.traverse((obj) => {
        if (obj.isMesh && obj.material) {
          const mats = Array.isArray(obj.material) ? obj.material : [obj.material]
          mats.forEach((mat) => {
            mat.transparent = true
            mat.opacity = fade * 0.9
          })
        }
      })
    })
  })

  return (
    <group ref={group}>
      {layout.map((item, i) => (
        <group key={i} position={item.position} scale={item.scale}>
          <MoleculeMesh palette={item.palette} opacity={0.92} />
        </group>
      ))}
    </group>
  )
}

function HeroMolecule({ progress }) {
  const root = useRef()

  useFrame((state, delta) => {
    if (!root.current) return
    const t = state.clock.elapsedTime
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, progress)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progress)

    if (progress < BEATS.transitStart) {
      // Float off-center, then lock to center
      heroTarget.set(
        lerp(2.1, 0, focus) + Math.sin(t * 0.5) * 0.06 * (1 - focus),
        lerp(0.55, 0, focus) + Math.cos(t * 0.65) * 0.05 * (1 - focus),
        lerp(1.2, 1.8, focus),
      )
    } else if (progress < BEATS.poreOutEnd) {
      // Travel through the nanopore along Z (toward camera / through membrane at z≈0)
      heroTarget.set(0, 0, lerp(1.8, -2.4, transit))
    } else {
      // Settle into the Q of AAGAMISEQ (slightly right of center)
      heroTarget.set(lerp(0, 1.55, brand), lerp(0, 0.05, brand), lerp(-2.4, 0.2, brand))
    }

    root.current.position.lerp(heroTarget, 1 - Math.exp(-delta * 7))
    root.current.rotation.x += delta * (0.35 + focus * 0.2)
    root.current.rotation.y += delta * (0.55 + transit * 0.25)

    const size = lerp(0.72, 1.15, focus) * lerp(1, 0.78, transit * 0.35) * lerp(1, 0.42, brand)
    root.current.scale.setScalar(size)
  })

  return (
    <group ref={root}>
      <MoleculeMesh palette={0} opacity={1} />
    </group>
  )
}

function Nanopore({ progress }) {
  const group = useRef()
  const sheet = useRef()
  const rim = useRef()
  const halo = useRef()
  const lattice = useRef()

  const visible =
    smooth(BEATS.poreInStart, BEATS.poreInEnd, progress) * (1 - smooth(BEATS.poreOutStart, BEATS.poreOutEnd, progress))

  useFrame((state, delta) => {
    if (!group.current) return
    const pulse = 1 + Math.sin(state.clock.elapsedTime * 1.6) * 0.018
    poreScale.set(pulse, pulse, 1)
    group.current.scale.lerp(poreScale, 1 - Math.exp(-delta * 5))
    group.current.visible = visible > 0.01
    if (sheet.current) sheet.current.opacity = visible * 0.55
    if (rim.current) rim.current.opacity = visible * 0.95
    if (halo.current) halo.current.opacity = visible * 0.35
    if (lattice.current) {
      lattice.current.traverse((obj) => {
        if (obj.material && 'opacity' in obj.material) obj.material.opacity = visible * 0.45
      })
    }
  })

  const nodes = useMemo(() => {
    const list = []
    for (let i = 0; i < 48; i += 1) {
      const a = (i / 48) * Math.PI * 2
      const r = 1.55 + seededRandom(i + 3) * 2.2
      list.push([Math.cos(a) * r, Math.sin(a) * r, (seededRandom(i + 9) - 0.5) * 0.08])
    }
    return list
  }, [])

  return (
    <group ref={group} position={[0, 0, 0]}>
      <mesh>
        <ringGeometry args={[1.05, 4.2, 96]} />
        <meshPhysicalMaterial
          ref={sheet}
          color="#8eb8b4"
          emissive="#2a6a68"
          emissiveIntensity={0.15}
          metalness={0.2}
          roughness={0.45}
          transparent
          side={THREE.DoubleSide}
          depthWrite={false}
        />
      </mesh>
      <mesh>
        <torusGeometry args={[1.05, 0.07, 16, 96]} />
        <meshPhysicalMaterial
          ref={rim}
          color="#5fdad1"
          emissive="#3ecfc0"
          emissiveIntensity={2.2}
          metalness={0.35}
          roughness={0.2}
          transparent
        />
      </mesh>
      <mesh>
        <torusGeometry args={[1.35, 0.025, 12, 96]} />
        <meshBasicMaterial ref={halo} color="#7ef0e4" transparent />
      </mesh>
      <group ref={lattice}>
        {nodes.map((pos, i) => (
          <mesh key={i} position={pos}>
            <sphereGeometry args={[0.045 + seededRandom(i) * 0.03, 8, 8]} />
            <meshPhysicalMaterial color="#a8d4d0" transparent opacity={0.4} roughness={0.4} />
          </mesh>
        ))}
      </group>
    </group>
  )
}

function MicroParticles({ progress }) {
  const points = useRef()
  const data = useRef(null)
  const clear = smooth(BEATS.clearStart, BEATS.clearEnd, progress)

  if (!data.current) {
    const count = 420
    const positions = new Float32Array(count * 3)
    const colors = new Float32Array(count * 3)
    const seeds = new Float32Array(count)
    const palette = [new THREE.Color('#b7fff0'), new THREE.Color('#5fdad1'), new THREE.Color('#9ad0ff')]
    for (let i = 0; i < count; i += 1) {
      const o = i * 3
      positions[o] = THREE.MathUtils.randFloatSpread(16)
      positions[o + 1] = THREE.MathUtils.randFloatSpread(9)
      positions[o + 2] = THREE.MathUtils.randFloat(-5, 4)
      seeds[i] = Math.random()
      const c = palette[i % palette.length]
      colors[o] = c.r
      colors[o + 1] = c.g
      colors[o + 2] = c.b
    }
    const geometry = new THREE.BufferGeometry()
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    data.current = { geometry, seeds, count }
  }

  useFrame((state) => {
    if (!points.current || !data.current) return
    const positions = data.current.geometry.attributes.position.array
    const { seeds, count } = data.current
    const t = state.clock.elapsedTime
    const opacity = 0.28 * (1 - clear)

    for (let i = 0; i < count; i += 1) {
      const o = i * 3
      const s = seeds[i]
      positions[o] += 0.0008 + s * 0.0012
      positions[o + 1] += Math.sin(t * (0.15 + s * 0.2) + s * 10) * 0.0007
      if (positions[o] > 8) positions[o] = -8
    }
    data.current.geometry.attributes.position.needsUpdate = true
    points.current.material.opacity = opacity
    points.current.visible = opacity > 0.02
  })

  return (
    <points ref={points} geometry={data.current.geometry}>
      <pointsMaterial
        vertexColors
        size={0.04}
        sizeAttenuation
        transparent
        opacity={0.28}
        depthWrite={false}
        blending={THREE.AdditiveBlending}
      />
    </points>
  )
}

function Effects() {
  const { gl, scene, camera } = useThree()
  const [postProcessing] = useState(() => new THREE.PostProcessing(gl))

  useEffect(() => {
    const scenePass = TSL.pass(scene, camera)
    const sceneColor = scenePass.getTextureNode('output')
    const bloomPass = bloom(sceneColor, 0.1, 0.65, 0.75)
    postProcessing.outputNode = sceneColor.add(bloomPass)
    postProcessing.needsUpdate = true
  }, [camera, postProcessing, scene])

  useFrame(() => postProcessing.render(), 1)
  return null
}
